 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Full uniform rows/columns are separator lines. The occupied seed tile
    # in the last region is repeated into the other regions.
    sep_rows = [r for r in range(h) if len(set(g[r])) == 1]
    sep_cols = [c for c in range(w) if len({g[r][c] for r in range(h)}) == 1]
    if sep_rows:
        cuts = [-1] + sep_rows + [h]
        bands = [(a + 1, b) for a, b in zip(cuts, cuts[1:]) if b > a + 1]
        seed_a, seed_b = bands[-1]
        seed = g[seed_a:seed_b]
        for a, b in bands[:-1]:
            for r in range(a, b):
                g[r] = seed[(r - a) % len(seed)][:]
    elif sep_cols:
        cuts = [-1] + sep_cols + [w]
        bands = [(a + 1, b) for a, b in zip(cuts, cuts[1:]) if b > a + 1]
        seed_a, seed_b = bands[0]
        for a, b in bands[1:]:
            for r in range(h):
                for c in range(a, b):
                    g[r][c] = g[r][seed_a + (c - a) % (seed_b - seed_a)]
    return g

